example.code:
export const UTM_SOURCES = { google: "google", meta: "meta", linkedin: "linkedin", email: "email" } as const;
export const UTM_MEDIUMS = { cpc: "cpc", paidSocial: "paid_social", email: "email" } as const;

export function utmLink(base: string, source: keyof typeof UTM_SOURCES, medium: keyof typeof UTM_MEDIUMS, campaign: string, content?: string): string {
  const u = new URL(base);
  u.searchParams.set("utm_source", UTM_SOURCES[source]);
  u.searchParams.set("utm_medium", UTM_MEDIUMS[medium]);
  u.searchParams.set("utm_campaign", campaign.toLowerCase());
  if (content) u.searchParams.set("utm_content", content.toLowerCase());
  return u.toString();
}
